/**
 * The pure part of memory-save: the project name, the save prompt, the reply
 * format and the checks that decide whether a new MEMORY.md may be written.
 */

export const SECTIONS = ['CRITICAL RULES', 'Architecture & Config Facts', 'Active Warnings', 'Topic Files'] as const
export type Section = (typeof SECTIONS)[number]

export const MAX_LINES = 200
export const MAX_CHARS = 50_000
export const SOFT_LINES = 160
export const SOFT_CHARS = 42_000
export const MAX_BULLET = 600

const PROJECT_NAME = /^[A-Za-z0-9._-]+$/
const TOPIC_FILE = /^[a-z0-9][a-z0-9._-]*\.md$/

export type Op =
  /** `section` is a heading of the file: one of the four sections, or a '### ' subheading. */
  | { op: 'add'; section: string; text: string }
  | { op: 'remove'; line: string }
  | { op: 'replace'; line: string; text: string }

export type TopicAppend = { file: string; append: string }

/** `refused` names each op or topic the mod could not read or place; the rest is still applied. */
export type Reply = { ops: Op[]; topics: TopicAppend[]; refused: string[] }

export type Parsed = { ok: true; reply: Reply } | { ok: false; error: string }

/**
 * `skipped` holds the lines of remove and replace ops the file has no line for. `retired` holds the
 * CRITICAL RULES bullets this save removed; they are counted in `removed` too.
 */
export type Changes = { added: number; removed: number; replaced: number; created: boolean; skipped: string[]; refused: string[]; retired: string[] }

export type Applied =
  | { ok: true; changed: false; skipped: string[]; refused: string[] }
  | { ok: true; changed: true; text: string; changes: Changes; newBullets: string[]; topics: TopicAppend[] }
  | { ok: false; error: string }

export type Inspection = {
  lines: number
  chars: number
  /** Whether the file has exactly the four sections, in order. */
  inFormat: boolean
  longBullets: { line: number; chars: number; head: string }[]
}

function trimSlashes(path: string): string {
  return path.replace(/\/+$/, '')
}

function baseName(path: string): string {
  return trimSlashes(path).split('/').at(-1) ?? ''
}

function parentOf(path: string): string {
  return trimSlashes(path).split('/').slice(0, -1).join('/')
}

/**
 * Returns the primary repository name from the git common dir, which names the
 * main repository also inside a worktree, or "" when the dir has neither shape.
 */
function nameFromCommonDir(commonDir: string): string {
  if (commonDir === '') return ''
  if (baseName(commonDir) === '.git') return baseName(parentOf(commonDir))
  const worktrees = parentOf(commonDir)
  if (baseName(worktrees) === 'worktrees' && baseName(parentOf(worktrees)) === '.git') {
    return baseName(parentOf(parentOf(worktrees)))
  }
  return ''
}

/**
 * Names the project the way `~/.claude/hooks/project.py` does, so the mod and
 * the classic hooks use the same memory directory: the primary repository,
 * else the git top level, else the working directory.
 */
export function projectNameFrom(commonDir: string, topLevel: string, cwd: string): string {
  const fromCommon = nameFromCommonDir(commonDir.trim())
  if (fromCommon !== '') return fromCommon
  const top = topLevel.trim()
  return top !== '' ? baseName(top) : baseName(cwd)
}

export function isProjectName(name: string): boolean {
  return PROJECT_NAME.test(name) && name !== '.' && name !== '..'
}

function linesOf(text: string): string[] {
  return text === '' ? [] : text.replace(/\n$/, '').split('\n')
}

function headingsOf(text: string): string[] {
  return linesOf(text)
    .filter(l => l.startsWith('## '))
    .map(l => l.slice(3).trim())
}

/** Whether the text has exactly the four sections, in order, and no other '## ' heading. */
function hasSections(headings: string[]): boolean {
  return headings.length === SECTIONS.length && SECTIONS.every((s, i) => s.toLowerCase() === headings[i]?.toLowerCase())
}

function foundText(headings: string[]): string {
  return headings.join(', ') || 'none'
}

function isHeading(line: string, section: string): boolean {
  return line.trim().toLowerCase() === `## ${section}`.toLowerCase()
}

export function inspect(text: string): Inspection {
  const lines = linesOf(text)
  const longBullets = lines.flatMap((line, i) =>
    line.startsWith('- ') && line.length > MAX_BULLET ? [{ line: i + 1, chars: line.length, head: line.slice(0, 55) }] : [],
  )
  return {
    lines: lines.length,
    chars: text.length,
    inFormat: hasSections(headingsOf(text)),
    longBullets,
  }
}

const EMPTY_SECTION = '- None yet.'

function trimBlank(lines: string[]): string[] {
  const start = lines.findIndex(l => l.trim() !== '')
  if (start === -1) return []
  const end = lines.length - [...lines].reverse().findIndex(l => l.trim() !== '')
  return lines.slice(start, end)
}

/** Splits a file into the lines before its first '## ' heading and the body of each section, by heading. */
function splitSections(text: string): { head: string[]; sections: [string, string[]][] } {
  const head: string[] = []
  const sections: [string, string[]][] = []
  for (const line of linesOf(text)) {
    if (line.startsWith('## ')) sections.push([line.slice(3).trim(), []])
    else (sections.at(-1)?.[1] ?? head).push(line)
  }
  return { head, sections }
}

/**
 * Where the content of a '## ' section that is not in the template waits,
 * under a '### Unsorted: <heading>' heading, until the fork moves each of its
 * bullets to the section it belongs in.
 */
const UNSORTED_HOME: Section = 'Architecture & Config Facts'
const UNSORTED = '### Unsorted: '

/**
 * Puts any file into the template: the four sections in order, a same-named
 * section merged into one, a missing one added as `- None yet.`, and every
 * other '## ' section kept as an unsorted part of Architecture & Config Facts
 * for the fork to sort. No content is dropped.
 */
export function repairSections(project: string, text: string): string {
  const { head, sections } = splitSections(text)
  const bodies = new Map<Section, string[]>()
  for (const [heading, body] of sections) {
    const section = sectionOf(heading)
    const lines = section === undefined ? [`${UNSORTED}${heading}`, '', ...trimBlank(body), ''] : trimBlank(body)
    const home = section ?? UNSORTED_HOME
    const before = bodies.get(home) ?? []
    bodies.set(home, trimBlank([...before, ...(before.length > 0 ? [''] : []), ...lines]))
  }
  const title = trimBlank(head)
  const parts = [title.length > 0 ? title.join('\n') : `# ${project}`]
  for (const section of SECTIONS) {
    const body = bodies.get(section) ?? []
    parts.push(`## ${section}\n\n${body.length > 0 ? body.join('\n') : EMPTY_SECTION}`)
  }
  return `${parts.join('\n\n')}\n`
}

/** Returns the four-section file a project starts from. */
export function skeleton(project: string): string {
  return `# ${project}\n\n${SECTIONS.map(s => `## ${s}\n`).join('\n')}`
}

/*
 * The rule texts below are the user's own, copied word for word from the classic memory-save Stop hook.
 * Only the parts about stopping are left out ("before stopping", "just stop", "this session"), because
 * the fork does not stop: it answers with JSON. Do not reword them.
 */

/** The writing rules for a project that has a MEMORY.md. */
const existingRules = (dir: string): string => `MANDATORY — these are HARD rules, not suggestions; apply each:
1. If you learned an ACTIVE PROJECT-SCOPED RULE that changes future behavior for this repository's code, commands, architecture, configuration, deployment, tests, or product preferences, you MUST record it in ${dir}/MEMORY.md in imperative mood — under '## CRITICAL RULES' when it is a behavior rule. Do NOT write global Claude Code behavior, shared skill workflow rules, general agent preferences, or cross-project policies to this project MEMORY.md; put those in the appropriate global instruction or shared skill file instead. If the scope is unclear, do not write it here.
2. NEVER write commit hashes, dated fix histories, completed-slice/feature DONE-records, or any archival narrative to MEMORY.md — these are FORBIDDEN there. ALL historical detail goes to a topic file ONLY — history.md by default, or a dedicated subject file when a topic grows large enough to warrant its own (list any new topic file under '## Topic Files'). Enforce this at WRITE time, not merely as an afterthought.
3. MEMORY.md holds ONLY durable rules, patterns, and stable facts, each as ONE focused bullet — strip narrative, examples, dated context, and completed-work detail to a topic file (history.md, or a dedicated subject file for a large topic). TWO caps BOTH apply: keep it under 200 lines AND under 50000 characters. Do NOT cram multiple ideas into one long line to dodge the line cap — the character cap catches that. If either is exceeded, move the oldest/least-critical entries to history.md.
4. Write in English ONLY. Rules 4 to 8 apply to MEMORY.md and to every topic file alike.
5. Write every entry to ASD-STE100 (Simplified Technical English): short sentences, active voice, simple tenses, ONE INSTRUCTION per sentence, and the SAME term for the same thing throughout. A reason clause is not a second instruction: keep the short 'because' or 'so that' clause whenever dropping it would let the rule be applied wrongly.
6. Name the fact directly. NEVER invent a metaphor or a figurative phrase, and NEVER present an invented phrase as if it were an established term. An invented phrase is unrecoverable months later, because the reader cannot tell which fact it encodes.
7. NEVER hedge a fact you measured. When you have NOT verified something, say exactly that instead of softening the claim, so a guess is never read back as a fact.
8. Reproduce identifiers, file names, config keys and trigger phrases exactly as they appear in the codebase, including non-English ones. Never translate them.`

const TEMPLATE = `MEMORY.md MUST use exactly these four sections, in this order:
  ## CRITICAL RULES        - non-negotiable project-scoped active rules, imperative mood
  ## Architecture & Config Facts - project-scoped stable technical context, not rules
  ## Active Warnings       - project-scoped pitfalls and recurring mistakes
  ## Topic Files           - pointers to detail files (e.g. history.md)
Only record project-scoped learnings in this project MEMORY.md. A learning is project-scoped only when it changes future behavior for this repository's code, commands, architecture, configuration, deployment, tests, or product preferences. Do not write global Claude Code behavior, shared skill workflow rules, general agent preferences, or cross-project policies to this project MEMORY.md. Put global rules in the appropriate global instruction or shared skill file instead. If the scope is unclear, do not write it here. Keep each bullet to ONE focused project rule or fact; strip narrative, examples, and dated context to a topic file (history.md, or a dedicated subject file for a large topic, listed under '## Topic Files'). TWO caps BOTH apply (under 200 lines AND under 50000 characters), so keep bullets concise and do NOT pad them into long single lines.`

/** The writing rules for a project without a MEMORY.md, followed by the template. */
const newProjectRules = (dir: string): string => `MANDATORY — this is a new project with no memory yet. You MUST create ${dir}/MEMORY.md following the template below, with project-scoped rules in imperative mood. Record only learnings that change future behavior for this repository's code, commands, architecture, configuration, deployment, tests, or product preferences. Do NOT write global Claude Code behavior, shared skill workflow rules, general agent preferences, or cross-project policies to this project MEMORY.md; put those in the appropriate global instruction or shared skill file instead. If the scope is unclear, do not write it here. NEVER write commit hashes or dated history to MEMORY.md — historical detail goes to a topic file only (history.md by default, or a dedicated subject file for a large topic). Keep it lean — bounded by BOTH a line cap (under 200) and a character cap (under 50000) — and in English ONLY. Every writing rule here applies to MEMORY.md and to every topic file alike. Each bullet is ONE focused project rule or fact; no narrative or padding. Write every entry to ASD-STE100 (Simplified Technical English): short sentences, active voice, simple tenses, ONE INSTRUCTION per sentence, and the SAME term for the same thing throughout; a reason clause is not a second instruction, so keep the short 'because' or 'so that' clause whenever dropping it would let the rule be applied wrongly. Name the fact directly: NEVER invent a metaphor or a figurative phrase, and never present an invented phrase as if it were an established term, because an invented phrase is unrecoverable months later. NEVER hedge a fact you measured, and when you have NOT verified something say exactly that instead of softening the claim, so a guess is never read back as a fact. Reproduce identifiers, file names, config keys and trigger phrases exactly as they appear in the codebase, including non-English ones, and never translate them. Skip this ONLY if the session was genuinely trivial with nothing project-scoped worth remembering.
${TEMPLATE}`

const MIGRATION = `MANDATORY MIGRATION: MEMORY.md is MISSING the '## CRITICAL RULES' section, so it is NOT in the required format. You MUST restructure the whole file into the four-section template, in this exact order:
  ## CRITICAL RULES        - non-negotiable project-scoped active rules, imperative mood
  ## Architecture & Config Facts - project-scoped stable technical context, not rules
  ## Active Warnings       - project-scoped pitfalls and recurring mistakes
  ## Topic Files           - pointers to detail files (e.g. history.md)
Preserve all real content, reorganize it under those sections, and convert rules to imperative mood.`

const FORMAT = `Answer with ONE JSON object and nothing else, no prose, no code fence:
{"ops": [...], "topics": [...]}
- {"op":"add","section":"<one of: ${SECTIONS.join(' | ')}, or a '### ' subheading the file already has, copied exactly>","text":"- <one bullet on one line>"}
- {"op":"remove","line":"<an existing line of MEMORY.md, copied exactly>"}
- {"op":"replace","line":"<an existing line, copied exactly>","text":"- <the new bullet on one line>"}
- topics: {"file":"history.md","append":"<markdown to append to that topic file>"}; a file name is lowercase, ends in .md, and is not MEMORY.md. The mod lists a new topic file under '## Topic Files'.
When nothing project-scoped was learned since the file was last written, answer {"ops":[],"topics":[]}.`

function sortNote(current: string): string {
  const parts = linesOf(current).filter(l => l.startsWith(UNSORTED))
  if (parts.length === 0) return ''
  return `MANDATORY SORT: the mod moved sections outside the template under these headings: ${parts.join(', ')}. In this answer, move every bullet under them to the section it belongs in (a remove op and an add op), move history to a topic file, and remove each '${UNSORTED}' heading line once its bullets are gone.`
}

/** How many lines and characters this save must remove, so the result is under the caps with room to spare. */
function mustRemove(state: Inspection): string {
  const lines = state.lines - (SOFT_LINES - 1)
  const chars = state.chars - (SOFT_CHARS - 1)
  const parts = [lines > 0 ? `${lines} line(s)` : '', chars > 0 ? `${chars} character(s)` : ''].filter(p => p !== '')
  return parts.join(' and ')
}

function sizeNotes(state: Inspection): string {
  const notes: string[] = []
  if (state.lines >= SOFT_LINES || state.chars >= SOFT_CHARS) {
    const overCap = state.lines >= MAX_LINES || state.chars >= MAX_CHARS
    const shrinkOnly = overCap
      ? ` MEMORY.md is ALREADY over a hard cap, so this save is a SHRINK-ONLY save: add NO new bullet, and remove at least ${mustRemove(state)}. A save that does not make the file smaller is refused, and nothing is written.`
      : ''
    notes.push(
      `MANDATORY OFFLOAD: MEMORY.md is now ${state.lines} lines / ${state.chars} characters — at or near a cap (BOTH limits apply: keep under 200 lines AND under 50000 characters). You MUST move the oldest/least-critical entries (resolved warnings, superseded facts, dated notes, completed-work records) to a topic file (history.md, or a dedicated subject file when a topic is large), leaving MEMORY.md a lean index of ACTIVE rules and current architecture facts. NEVER move or remove a bullet under '## CRITICAL RULES' in this save: the mod refuses that remove; shorten such a bullet with a replace op instead. Remove at least ${mustRemove(state)} in THIS save.${shrinkOnly}`,
    )
  }
  if (state.longBullets.length > 0) {
    const list = state.longBullets.map(b => `  - line ${b.line} (${b.chars} chars): ${b.head}...`).join('\n')
    notes.push(
      `MANDATORY BULLET SPLIT: ${state.longBullets.length} bullet(s) exceed ${MAX_BULLET} characters — a single bullet this long soft-wraps in an editor and is unscannable. Each bullet MUST be ONE focused rule or fact. Fix each by EITHER splitting it into multiple focused bullets, OR moving its detail (recipe steps, examples, multi-aspect notes) to a topic file and leaving the load-bearing rule as a lean line with a '(detail in <topic>.md)' pointer. Prefer SPLITTING for '## CRITICAL RULES' (only that section is re-injected periodically, so its detail must stay in MEMORY.md) and OFFLOADING for architecture facts. The exception is an irreducible safety rule whose detail is the rule itself (e.g. an exact regex/command) — keep it whole. Over-cap bullets:\n${list}`,
    )
  }
  return notes.join('\n')
}

function skippedNote(skipped: readonly string[]): string {
  if (skipped.length === 0) return ''
  const list = skipped.map(l => `  - ${l}`).join('\n')
  return `MANDATORY EXACT COPY: the last save skipped these remove or replace lines, because MEMORY.md has no line equal to them. Copy the "line" of a remove or replace op character for character from the file above, with its markup: do not add or drop a list marker, bold, italics or backticks. Skipped:\n${list}`
}

function refusedNote(refused: readonly string[]): string {
  if (refused.length === 0) return ''
  const list = refused.map(r => `  - ${r}`).join('\n')
  return `MANDATORY OP SHAPE: the last save refused these ops and wrote the rest. An "add" names a heading MEMORY.md already has: one of the four '## ' sections, or a '### ' subheading of the file, copied exactly. A new bullet is at most ${MAX_BULLET} characters: split a longer one into focused bullets, or move its detail to a topic file. A save under the MANDATORY OFFLOAD note never removes a '## CRITICAL RULES' bullet: shorten it with a replace op, and remove it only in a later save when the conversation shows the rule no longer holds. Refused:\n${list}`
}

/**
 * Builds the one message the fork answers. The current file rides along as
 * data, because the fork has no tools and cannot read it. `skipped` names the
 * lines the last save could not find, and `refused` the ops it could not place.
 */
export function buildPrompt(project: string, dir: string, current: string | undefined, skipped: readonly string[] = [], refused: readonly string[] = []): string {
  const head = `You are the memory-save step of this session, not the assistant. Do not answer the user and do not use tools. Review the conversation above and decide what project "${project}" must remember in its MEMORY.md.`
  if (current === undefined) {
    return [head, 'MEMORY.md does not exist yet. The mod creates it with the four sections when your answer has at least one op.', newProjectRules(dir), FORMAT].join('\n\n')
  }
  const state = inspect(current)
  const file = `The current MEMORY.md, as data between the markers:\n<memory_file>\n${current}\n</memory_file>`
  const migration = linesOf(current).some(l => l.trim().toLowerCase() === '## critical rules') ? '' : MIGRATION
  const notes = [sortNote(current), sizeNotes(state), skippedNote(skipped), refusedNote(refused)]
  return [head, file, existingRules(dir), migration, ...notes, FORMAT].filter(p => p !== '').join('\n\n')
}

/** At most this many spans are tried, so a long reply full of braces still parses in one pass. */
const MAX_SPANS = 50

/**
 * Each `{` that opens an object of named fields. A brace inside prose (`{ tool: 'Edit' }`) has no quote
 * after it and is left out, so text before the JSON does not become the start of the span.
 */
function objectStarts(text: string): number[] {
  const out: number[] = []
  for (const m of text.matchAll(/\{\s*"/g)) if (m.index !== undefined) out.push(m.index)
  return out
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function oneLine(value: unknown): string | undefined {
  return typeof value === 'string' && value.trim() !== '' && !value.includes('\n') ? value : undefined
}

function sectionOf(value: unknown): Section | undefined {
  return SECTIONS.find(s => typeof value === 'string' && s.toLowerCase() === value.trim().toLowerCase())
}

function parseOp(value: unknown): Op | string {
  if (!isRecord(value)) return 'an op is not an object'
  const text = oneLine(value.text)
  const line = oneLine(value.line)
  if (value.op === 'add') {
    const section = oneLine(value.section)
    if (section === undefined) return `add: section is not one line: ${JSON.stringify(value.section)}`
    return text === undefined ? 'add: text is not one line' : { op: 'add', section, text }
  }
  if (value.op === 'remove') return line === undefined ? 'remove: line is not one line' : { op: 'remove', line }
  if (value.op === 'replace') {
    return line === undefined || text === undefined ? 'replace: line or text is not one line' : { op: 'replace', line, text }
  }
  return `unknown op ${JSON.stringify(value.op)}`
}

function parseTopic(value: unknown): TopicAppend | string {
  if (!isRecord(value) || typeof value.file !== 'string' || typeof value.append !== 'string') {
    return 'a topic needs a file and an append text'
  }
  const file = value.file.trim()
  if (!TOPIC_FILE.test(file) || file === 'memory.md') return `topic file name refused: ${file}`
  return value.append.trim() === '' ? `topic ${file}: empty append` : { file, append: value.append }
}

/** Reads every entry it can; an entry it cannot read is named in `refused` and the rest is kept. */
function listOf<T>(value: unknown, parse: (v: unknown) => T | string, refused: string[]): T[] | string {
  if (value === undefined) return []
  if (!Array.isArray(value)) return 'ops and topics must be arrays'
  const items: T[] = []
  for (const raw of value) {
    const item = parse(raw)
    if (typeof item === 'string') refused.push(item)
    else items.push(item)
  }
  return items
}

function parseSpan(span: string): Record<string, unknown> | string {
  let value: unknown
  try {
    value = JSON.parse(span)
  } catch (err) {
    return `reply is not valid JSON (${err instanceof Error ? err.message : String(err)})`
  }
  return isRecord(value) ? value : 'reply is not a JSON object'
}

/**
 * The reply's own JSON object. The span always ends at the last `}`, and the first start that parses is
 * the outermost object, so a reply that writes a sentence before the JSON is still read.
 */
function decode(text: string): Record<string, unknown> | string {
  const end = text.lastIndexOf('}')
  const starts = objectStarts(text).filter(i => i < end).slice(0, MAX_SPANS)
  if (starts.length === 0) return 'reply has no JSON object'
  let last = 'reply has no JSON object'
  for (const start of starts) {
    const value = parseSpan(text.slice(start, end + 1))
    if (typeof value !== 'string') return value
    last = value
  }
  return last
}

/** A fork result with no text to read, by the reason the engine gives. */
export type Unanswered =
  | { reason: 'nothing-to-fork' }
  | { reason: 'api-error'; status: number | null; error: string }
  | { reason: 'empty-reply' }
  | { reason: 'aborted' }

export function unansweredText(r: Unanswered): string {
  if (r.reason === 'nothing-to-fork') return 'the fork had nothing to fork yet'
  if (r.reason === 'empty-reply') return 'the fork replied with no text'
  if (r.reason === 'aborted') return 'the fork was cut before its reply'
  return `the fork got an API error, ${r.status ?? 'no response'} (${r.error})`
}

/**
 * Reads the fork's answer. A reply that is not one JSON object is an error, never a guess. An op or a
 * topic of another shape is named in `refused` and the rest of the reply is kept, because one bad entry
 * must not lose the whole save.
 */
export function parseReply(text: string): Parsed {
  const value = decode(text)
  if (typeof value === 'string') return { ok: false, error: value }
  const refused: string[] = []
  const ops = listOf(value.ops, parseOp, refused)
  if (typeof ops === 'string') return { ok: false, error: ops }
  const topics = listOf(value.topics, parseTopic, refused)
  if (typeof topics === 'string') return { ok: false, error: topics }
  return { ok: true, reply: { ops, topics, refused } }
}

function bullet(text: string): string {
  const t = text.trim()
  return t.startsWith('- ') ? t : `- ${t.replace(/^[-*]\s*/, '')}`
}

function sectionEnd(lines: string[], start: number): number {
  const next = lines.findIndex((l, i) => i > start && l.startsWith('## '))
  return next === -1 ? lines.length : next
}

const HEADING = /^#{2,3} /

function headingName(line: string): string {
  return line.replace(/^#+\s*/, '').trim().toLowerCase()
}

/** The line of the heading an add op names: one of the four sections, or a '### ' subheading of the file. */
function headingIndex(lines: string[], name: string): number {
  const want = headingName(name)
  return lines.findIndex(l => HEADING.test(l) && headingName(l) === want)
}

/** The end of a heading's own block: the next heading of any level, so a bullet stays under its own heading. */
function blockEnd(lines: string[], start: number): number {
  const next = lines.findIndex((l, i) => i > start && HEADING.test(l))
  return next === -1 ? lines.length : next
}

function addTo(lines: string[], section: string, text: string): string | undefined {
  const start = headingIndex(lines, section)
  if (start === -1) return `add: unknown section ${JSON.stringify(section)}`
  let at = blockEnd(lines, start)
  while (at > start + 1 && (lines[at - 1] ?? '').trim() === '') at--
  const body = lines.slice(start + 1, at).filter(l => l.trim() !== '')
  if (body.length === 1 && /^- none yet\.?$/i.test(body[0]?.trim() ?? '')) lines.splice(at - 1, 1, text)
  else if (at === start + 1) lines.splice(at, 0, '', text)
  else lines.splice(at, 0, text)
  return undefined
}

function withoutMarker(line: string): string {
  return line.trim().replace(/^[-*]\s+/, '')
}

/**
 * The index of the line an op names: the exact line, else the one line that
 * differs from it only by a leading list marker. The fork writes every entry
 * as a bullet, also one that stands in the file as a plain paragraph line.
 */
function indexOfLine(lines: string[], line: string): number {
  const exact = lines.findIndex(l => l.trimEnd() === line.trimEnd())
  if (exact !== -1) return exact
  const bare = withoutMarker(line)
  const loose = bare === '' ? [] : lines.flatMap((l, i) => (withoutMarker(l) === bare ? [i] : []))
  return loose.length === 1 ? (loose[0] ?? -1) : -1
}

/** A bullet over the cap is refused as its own op, so the other ops of the same reply are still written. */
function tooLong(kind: Op['op'], text: string): string | undefined {
  return text.length > MAX_BULLET ? `${kind}: bullet of ${text.length} characters, the limit is ${MAX_BULLET}: ${text.slice(0, 60)}…` : undefined
}

/** Whether line `at` sits under '## CRITICAL RULES': the last '## ' heading above it is that section. */
function inCriticalRules(lines: string[], at: number): boolean {
  for (let i = at; i >= 0; i--) {
    const line = lines[i] ?? ''
    if (line.startsWith('## ')) return isHeading(line, 'CRITICAL RULES')
  }
  return false
}

/**
 * What one save's ops share: the bullets they wrote, whether the save runs under the size offload note,
 * and the CRITICAL RULES bullets it removed.
 */
type Work = { newBullets: string[]; offload: boolean; retired: string[] }

/** Whether the file is at or over the soft caps, where the prompt tells the fork to move entries out. */
function atSoftCap(current: string | undefined): boolean {
  if (current === undefined) return false
  const state = inspect(current)
  return state.lines >= SOFT_LINES || state.chars >= SOFT_CHARS
}

/** Why the line a remove or replace names must stay, or undefined when the op may change it. */
function keptLine(lines: string[], at: number, op: Exclude<Op, { op: 'add' }>, offload: boolean): string | undefined {
  // A '### ' subheading may go (the fork removes an 'Unsorted' line once its bullets moved); the title and
  // the four '## ' sections may not, because the file must stay in the template.
  if (/^#{1,2} /.test(lines[at] ?? '')) return `${op.op}: the line is a section heading: ${op.line.slice(0, 60)}`
  // A size offload chose user rules to move out (measured on a project at the soft line cap), so a
  // CRITICAL RULES bullet goes only in a save without that note, where the fork found it no longer holds.
  if (op.op === 'remove' && offload && inCriticalRules(lines, at)) return `remove: the line is a CRITICAL RULES bullet, and this save only makes room: ${op.line.slice(0, 60)}`
  return undefined
}

function applyOp(lines: string[], op: Op, work: Work): string | undefined {
  if (op.op === 'add') {
    const text = bullet(op.text)
    const error = tooLong('add', text) ?? addTo(lines, op.section, text)
    if (error === undefined) work.newBullets.push(text)
    return error
  }
  const at = indexOfLine(lines, op.line)
  if (at === -1) return `${op.op}: line not found: ${op.line.slice(0, 60)}`
  const kept = keptLine(lines, at, op, work.offload)
  if (kept !== undefined) return kept
  if (op.op === 'remove') {
    if (inCriticalRules(lines, at)) work.retired.push(lines[at] ?? op.line)
    lines.splice(at, 1)
    return undefined
  }
  const text = bullet(op.text)
  const long = tooLong('replace', text)
  if (long !== undefined) return long
  work.newBullets.push(text)
  lines[at] = text
  return undefined
}

/** A retired CRITICAL RULES bullet is kept in history.md, so a wrong removal can be put back. */
function retiredTopic(retired: readonly string[]): TopicAppend[] {
  return retired.length === 0 ? [] : [{ file: 'history.md', append: `## Retired CRITICAL RULES\n\n${retired.join('\n')}` }]
}

function tally(ops: Op[], created: boolean, skipped: string[], refused: string[], retired: string[]): Changes {
  const count = (kind: Op['op']): number => ops.filter(o => o.op === kind).length
  return { added: count('add'), removed: count('remove'), replaced: count('replace'), created, skipped, refused, retired }
}

/** Lists every topic file the reply writes under '## Topic Files' when the file does not name it yet. */
function pointTopics(lines: string[], topics: TopicAppend[], newBullets: string[], refused: string[]): void {
  for (const { file } of topics) {
    const start = lines.findIndex(l => isHeading(l, 'Topic Files'))
    const listed = start !== -1 && lines.slice(start, sectionEnd(lines, start)).some(l => l.includes(file))
    if (listed) continue
    const error = addTo(lines, 'Topic Files', `- \`${file}\`.`)
    if (error === undefined) newBullets.push(`- \`${file}\`.`)
    else refused.push(`topic ${file}: ${error}`)
  }
}

/**
 * Applies the reply to the current file. A missing file starts from the
 * skeleton. A remove or replace whose line the file lacks is skipped and
 * named, and an add whose heading the file lacks is refused and named: the rest
 * is applied, because one bad op is no reason to lose the others. The result is
 * not checked here; `validate` checks it.
 */
export function apply(project: string, current: string | undefined, reply: Reply): Applied {
  const lines = linesOf(current ?? skeleton(project))
  const newBullets: string[] = []
  const done: Op[] = []
  const skipped: string[] = []
  const refused = [...reply.refused]
  const work: Work = { newBullets, offload: atSoftCap(current), retired: [] }
  for (const op of reply.ops) {
    if (op.op !== 'add' && indexOfLine(lines, op.line) === -1) {
      skipped.push(op.line)
      continue
    }
    const error = applyOp(lines, op, work)
    if (error !== undefined) refused.push(error)
    else done.push(op)
  }
  if (done.length === 0 && reply.topics.length === 0) return { ok: true, changed: false, skipped, refused }
  const topics = [...reply.topics, ...retiredTopic(work.retired)]
  pointTopics(lines, topics, newBullets, refused)
  const changes = tally(done, current === undefined, skipped, refused, work.retired)
  return { ok: true, changed: true, text: `${lines.join('\n')}\n`, changes, newBullets, topics }
}

/** `2 skipped, not in the file: - Walk a backfill…; - Old note…` */
export function skippedText(skipped: readonly string[]): string {
  return `${skipped.length} skipped, not in the file: ${skipped.map(l => (l.length > 60 ? `${l.slice(0, 60)}…` : l)).join('; ')}`
}

/**
 * Whether this save is a step back from a file that is already over a cap: smaller in both measures and
 * smaller in at least one. Such a step is written, because a file over a cap can only come back in steps,
 * and refusing it leaves the project with no save at all.
 */
function isShrinkStep(state: Inspection, current: string | undefined): boolean {
  if (current === undefined) return false
  const before = inspect(current)
  if (before.lines < MAX_LINES && before.chars < MAX_CHARS) return false
  return state.lines <= before.lines && state.chars <= before.chars && (state.lines < before.lines || state.chars < before.chars)
}

/** Returns why the new file must not be written, or an empty list. `current` is the file before this save. */
export function validate(text: string, newBullets: string[], current?: string): string[] {
  const errors: string[] = []
  const headings = headingsOf(text)
  if (!hasSections(headings)) errors.push(`sections are not exactly ${SECTIONS.join(', ')} (found: ${foundText(headings)})`)
  const state = inspect(text)
  const step = isShrinkStep(state, current)
  if (state.lines >= MAX_LINES && !step) errors.push(`${state.lines} lines, the limit is under ${MAX_LINES}`)
  if (state.chars >= MAX_CHARS && !step) errors.push(`${state.chars} characters, the limit is under ${MAX_CHARS}`)
  const long = newBullets.filter(b => b.length > MAX_BULLET)
  if (long.length > 0) errors.push(`${long.length} new bullet(s) over ${MAX_BULLET} characters`)
  return errors
}

/** The same reply without its adds and topic appends, so a save over a cap still writes its removes. */
function withoutAdds(reply: Reply): Reply {
  return { ops: reply.ops.filter(op => op.op !== 'add'), topics: [], refused: reply.refused }
}

/** The result of the shrinking second pass, or the first pass's errors when that pass writes nothing either. */
function shrunk(project: string, current: string | undefined, reply: Reply, errors: string[]): Applied {
  const second = apply(project, current, withoutAdds(reply))
  if (!second.ok || !second.changed || validate(second.text, second.newBullets, current).length > 0) {
    return { ok: false, error: `not written: ${errors.join('; ')}` }
  }
  const dropped = reply.ops.filter(op => op.op === 'add').length + reply.topics.length
  const note = `over a cap (${errors.join('; ')}): ${dropped} add(s) and topic append(s) dropped, the removes were written`
  return { ...second, changes: { ...second.changes, refused: [...second.changes.refused, note] } }
}

/**
 * The save to write. A result over a line or character cap is not lost: the adds and topic appends are
 * dropped and the removes alone are written, so the file comes down instead of the whole save failing.
 */
export function fit(project: string, current: string | undefined, reply: Reply): Applied {
  const first = apply(project, current, reply)
  if (!first.ok || !first.changed) return first
  const errors = validate(first.text, first.newBullets, current)
  return errors.length === 0 ? first : shrunk(project, current, reply, errors)
}

/** Returns the topic file after the append; a new file gets a title. */
export function appendTopic(project: string, file: string, existing: string | undefined, append: string): string {
  const base = existing ?? `# ${project}: ${file.replace(/\.md$/, '')}\n`
  const sep = base.endsWith('\n\n') ? '' : base.endsWith('\n') ? '\n' : '\n\n'
  return `${base}${sep}${append.trim()}\n`
}

export const BACKUP = 'MEMORY.pre-migration.md'

function count(n: number, word: string): string {
  return `${n} ${word}`
}

/** One line for the log, naming what the save changed. */
export function changeText(changes: Changes, topics: TopicAppend[]): string {
  const parts: string[] = []
  if (changes.created) parts.push('created')
  if (changes.added > 0) parts.push(count(changes.added, 'added'))
  if (changes.removed > 0) parts.push(count(changes.removed, 'removed'))
  if (changes.replaced > 0) parts.push(count(changes.replaced, 'replaced'))
  const files = [...new Set(topics.map(t => t.file))]
  const topicPart = files.length > 0 ? `; appended to ${files.join(', ')}` : ''
  const skippedPart = changes.skipped.length > 0 ? `; ${skippedText(changes.skipped)}` : ''
  const refusedPart = changes.refused.length > 0 ? `; refused: ${changes.refused.join('; ')}` : ''
  const retiredPart = changes.retired.length > 0 ? `; retired from CRITICAL RULES, kept in history.md: ${changes.retired.join('; ')}` : ''
  return `MEMORY.md: ${parts.join(', ') || 'topic files only'}${topicPart}${skippedPart}${refusedPart}${retiredPart}`
}

/** How many characters of the last event the sidebar's second line holds. */
const MAX_EVENT = 120

/**
 * The last transcript line as the sidebar's second line: the section's own title is left off the
 * front, and a long line is cut, because the pane holds one row for it.
 */
export function eventShort(text: string): string {
  const body = text.replace(/^MEMORY\.md: /, '')
  return body.length > MAX_EVENT ? `${body.slice(0, MAX_EVENT - 1)}…` : body
}

const SHORT_TOPICS = 3

/** The topic files a save appended to, without `.md`: the first three and the count of the rest. */
function topicNames(topics: TopicAppend[]): string {
  const names = [...new Set(topics.map(t => t.file.replace(/\.md$/, '')))]
  const rest = names.length - SHORT_TOPICS
  return `topic: ${names.slice(0, SHORT_TOPICS).join(', ')}${rest > 0 ? ` +${rest}` : ''}`
}

/** How the sidebar colours a line or a part of one. */
export type Tone = 'ok' | 'warn' | 'error' | 'dim'
export type Part = { text: string; kind?: Tone }

const part = (text: string, kind: Tone | undefined): Part => (kind === undefined ? { text } : { text, kind })

/** Parts with a separator between each two, the separator in the line's own colour. */
function joinParts(parts: Part[], sep: string): Part[] {
  return parts.flatMap((p, i) => (i === 0 ? [p] : [part(sep, undefined), p]))
}

/**
 * The short form for the status line, in parts: what was written green, and each part the save left
 * out or a rule it retired yellow, so the person sees a rule leave and can put it back.
 */
export function changeParts(changes: Changes, topics: TopicAppend[]): Part[] {
  const counts: [string, number][] = [
    ['+', changes.added],
    ['-', changes.removed],
    ['~', changes.replaced],
  ]
  const written = counts.filter(([, n]) => n > 0).map(([sign, n]) => `${sign}${n}`)
  if (topics.length > 0) written.push(topicNames(topics))
  const left: [number, string][] = [
    [changes.skipped.length, 'skipped'],
    [changes.refused.length, 'refused'],
    [changes.retired.length, 'rule(s) retired'],
  ]
  const warned = left.filter(([n]) => n > 0).map(([n, what]) => part(`${n} ${what}`, 'warn'))
  const all = [...(written.length > 0 ? [part(written.join(' '), 'ok')] : []), ...warned]
  return all.length === 0 ? [part('saved', 'ok')] : joinParts(all, ' ')
}

/** The short form for the status line. */
export function changeShort(changes: Changes, topics: TopicAppend[]): string {
  return changeParts(changes, topics).map(p => p.text).join('')
}

/** A save that changed no file, faint, with the lines it skipped and the ops it refused yellow. */
export function noChangeParts(skipped: number, refused: number): Part[] {
  const counts = [skipped > 0 ? `${skipped} skipped` : '', refused > 0 ? `${refused} refused` : ''].filter(p => p !== '')
  if (counts.length === 0) return [part('no change', 'dim')]
  return [part('no change', 'dim'), part(', ', undefined), part(counts.join(', '), 'warn')]
}

/** An error as `error: <message>`, only the front red. */
export function errorParts(text: string): Part[] {
  return [part('error:', 'error'), part(` ${text}`, undefined)]
}

/** Returns the topic files among a directory's entries: every other `.md` file but the migration backup. */
export function topicFiles(names: readonly string[]): string[] {
  return names.filter(n => n.endsWith('.md') && n !== 'MEMORY.md' && n !== BACKUP).sort()
}

/**
 * The reply language rule. Long turns whose context is mostly English (tool output, docs, this file)
 * ended with English replies to Turkish prompts (measured), so the rule names that case.
 */
export const LANGUAGE_NOTE = 'Answer in the language of the user\'s own messages, in every reply and every progress line, also at the end of a long turn whose context (tool output, docs, this memory) is in another language. Keep technical terms and identifiers as they are.'

/**
 * The text the session starts with: the reply language rule, the whole MEMORY.md and the topic files
 * next to it. The file holds no instruction to write it, because the mod does.
 */
export function contextText(project: string, dir: string, memory: string, topics: readonly string[]): string {
  const head = `[PROJECT MEMORY: ${project}]\n${LANGUAGE_NOTE}\n\n${memory.trim()}`
  return topics.length === 0 ? head : `${head}\n\nTopic files in ${dir}: ${topics.join(', ')}`
}

export function clockText(ms: number): string {
  const d = new Date(ms)
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

